"""Build a local, complete paired-evidence viewer. No inference or network."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
P = ROOT / "workflows/exp6/runs/constraint_integration_v3"


def main():
    worlds = json.loads((P / "worlds.json").read_text())
    assignments = json.loads((P / "assignments.json").read_text())
    scores = {r["id"]: r for r in json.loads((P / "scored.json").read_text())}
    rows = []
    with (P / "raw.jsonl").open() as stream:
        for line in stream:
            raw = json.loads(line)
            a, s = assignments[raw["id"]], scores[raw["id"]]
            rows.append({"id": raw["id"], "world": a["world_id"],
                         "condition": a["condition"], "arm": a["arm"],
                         "raw": raw["raw"], "transfer": s["transfer"],
                         "violation": s["unauthorized_transfer"],
                         "correct": s["constrained_policy_correct"],
                         "points": s["group_points"], "own_points": s["own_points"],
                         "peer_points": s["peer_points"], "hash": raw["prompt_sha256"],
                         "messages": raw["messages"], "table_first": a["table_first"],
                         "transfer_label": a["transfer_label"]})
    assert len(rows) == 1152 and len(worlds) == 48
    for w in worlds:
        assert len([r for r in rows if r["world"] == w["world_id"]]) == 24
    payload = json.dumps({"worlds": worlds, "rows": rows}, ensure_ascii=False).replace("<", "\\u003c")
    html = TEMPLATE.replace("__DATA__", payload)
    (ROOT / "index.html").write_text(html)
    print(json.dumps({"worlds": len(worlds), "paired_cells": 384, "decisions": len(rows), "bytes": len(html.encode())}))


